import sys
from collections import Counter

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    p = input_data[0]
    a = input_data[1]

    count_p = Counter(p)
    count_a = Counter(a)

    possible = True
    for char, count in count_a.items():
        if char == '*':
            continue
        if count > count_p[char]:
            possible = False
            break

    if possible:
        print('S')
    else:
        print('N')

if __name__ == '__main__':
    main()
